// command-registry.mjs — the single source of truth for the fgos CLI's
// machine-readable verb manifest (`fgos --help --json`), mirroring the
// `.bee/bin/lib/command-registry.mjs` precedent (entry-standardization P37,
// deliverable b).
//
// Pure data only — no imports of verb logic (src/state, src/runner, etc.), so
// this module sits at the `kernel` layer in docs/architecture-manifest.json:
// `bin/fgos.mjs` (entry) importing it is a downward import, and this file can
// never import back up into anything that would create a cycle.
//
// Each entry's `parameters` field is JSON-Schema in the same
// {type:"object", properties, required} shape bee's registry uses — the
// manifest is zero-translation for any tool-schema-based agent.
//
// `touchesState`/`externalEffect` (str46-io-contract D4, superseding the
// prior single `access` field) are two independent per-verb declarations: the
// former is true for any verb that ever appends an event or overwrites
// `.fgos/state.json`; the latter is true only for a verb with a real effect
// OUTSIDE `.fgos/` (today: `review --github`/`approve --github`, which touch
// a real GitHub PR). A verb with more than one sub-mode (review, evolve,
// session) is classified by its most-privileged effect on each axis — e.g.
// `evolve` with no flags is a pure read but `evolve --submit` appends a work
// item, so the whole verb declares `touchesState: true`. Both flags are
// declarations only: P37/this cell do not wire them into dispatch/authz
// (that is P38's job).
//
// `paginated` (str46-io-contract D5/D35) declares whether the verb's result
// accepts --cursor/--limit (opaque cursor, per cursor.mjs) — true only for
// `ready`/`triage`/`evolve`/`list`, the four verbs whose result can grow
// unboundedly with data. Every entry carries this field (even the 30 that
// are `false`) so a transport can read pagination support machine-readably
// instead of guessing per verb.
//
// `requiresExistingStore` (tsk-4fu-2) is narrower than `touchesState`: true
// only for a verb whose handler actually reads/writes through the CLI's own
// `dataDir()` (the strict, cwd-resolved `.fgos/` — bin/fgos.mjs's `dir`
// param). A verb can be `touchesState: true` without this — `session`
// writes `.fgos/sessions.json` through its own independent, git-resolved
// path (session.mjs, D10 symlink actor), never through `dir`, and `setup`
// touches the shared config file/shell rc files/git hooks, never `.fgos/` at
// all — so gating either of those on `dir`'s existence would refuse for a
// reason that has nothing to do with what they actually do. `init` is also
// `false` here despite being the one verb that legitimately creates
// `.fgos/`: it gets the opposite check (refuse inside a linked worktree,
// via `isMainWorktree`), not this one. Every entry carries this field, same
// discipline as `paginated` above.

//
// `subcommands` (optional) is set on a verb whose first positional is a
// sub-verb: {<sub>: {description, parameters, examples}}, each sub-verb's
// `parameters` in the same JSON-Schema shape, holding only the flags that
// sub-verb reads. The verb-level `parameters` of such a verb is derived from
// it by withSubcommands(), so the sub-verb list has one source.
// test/cli/subcommand-flag-drift.test.mjs checks each sub-verb's schema
// against the flags its handler really reads.

export const MANIFEST_SCHEMA_VERSION = '3.0';

// Top-level tokens the Rust host routes to the legacy-node payload as the
// manifest door (`fgos --help [<verb>] [--json]`), next to the verb
// selectors: scripts/export-command-selectors.mjs writes a route for each.
export const HELP_SELECTORS = ['--help', '-h'];

function withSubcommands(entry) {
  return {
    ...entry,
    parameters: {
      type: 'object',
      properties: {
        sub: {
          type: 'string',
          description: 'Sub-verb (positional); its own flags are under subcommands.<sub>.parameters.',
          enum: Object.keys(entry.subcommands),
        },
      },
      positional: ['sub'],
      required: ['sub'],
    },
  };
}

export const COMMAND_REGISTRY = [
  withSubcommands({
    name: 'worktree', invoke: 'fgos worktree create <path> [--branch <name> | --detach] [--base <ref>] | fgos worktree remove <path> --delivered-to <ref>',
    description: 'Create a registered worker checkout under worktree-admin, or remove one after proving it clean, idle and delivered.',
    subcommands: { create: {
      description: 'Create a named branch or a detached checkout (the default). Dependency provisioning is a separate consumer step.',
      parameters: { type: 'object', properties: { path: { type: 'string' }, branch: { type: 'string' }, detach: { type: 'boolean' }, base: { type: 'string' } }, positional: ['path'], required: ['path'] },
      examples: ['fgos worktree create ../worker --branch task/example', 'fgos worktree create ../scratch --detach'],
    }, remove: {
      description: 'Remove a worktree. Refuses a dirty checkout, one a process stands in, worker state to preserve, or a tip not contained in --delivered-to; there is no force flag. --delivered-to takes a branch name, a full ref or an object id.',
      parameters: { type: 'object', properties: { path: { type: 'string' }, 'delivered-to': { type: 'string' } }, positional: ['path'], required: ['path', 'delivered-to'] },
      examples: ['fgos worktree remove ../worker --delivered-to main'],
    } },
    examples: ['fgos worktree create ../worker --branch task/example', 'fgos worktree create ../scratch --detach', 'fgos worktree remove ../worker --delivered-to main'],
    touchesState: false, requiresExistingStore: false, externalEffect: true, paginated: false, deprecated: null,
  }),
  {
    name: 'version',
    invoke: 'fgos version',
    description: 'Report this build\'s own package version, git commit (when resolvable), and the full verb set it dispatches -- the hook-safe, scriptable way to tell an old install apart from a current checkout without reading node_modules directly (tsk-2ej). Works with no .fgos/ store present.',
    parameters: {
      type: 'object',
      properties: {
        'runtime-json': { type: 'boolean', description: 'Also report the running release (host, artifact digest) next to the package version.' },
      },
      required: [],
    },
    examples: ['fgos version', 'fgos version --runtime-json'],
    touchesState: false,
    requiresExistingStore: false,
    externalEffect: false,
    paginated: false,
    deprecated: null,
  },
  withSubcommands({
    name: 'metrics',
    invoke: 'fgos metrics <subcommand>',
    description: 'Observation metrics suite (cases, harness scorecard, runs, run coverage, discussions and passive agreement, eval records, outcomes, entropy, snapshot). Native Rust host command.',
    subcommands: {
      ping: {
        description: 'Health check: echoes the resolved root and any stdin length.',
        parameters: { type: 'object', properties: {}, required: [] },
        examples: ['fgos metrics ping'],
      },
      case: {
        description: 'Measured cases: "open <name> --harness fgos|cook-plan|plain [--task]" starts one, "close <name> --interventions <N> --verdict usable|fixed|discarded" ends it, "list" lists them (--open: only open ones).',
        parameters: {
          type: 'object',
          properties: {
            action: { type: 'string', description: 'Positional: open, close or list.', enum: ['open', 'close', 'list'] },
            name: { type: 'string', description: 'Positional after open/close: the case name.' },
            harness: { type: 'string', description: 'open: the harness measured (fgos, cook-plan, plain).' },
            task: { type: 'string', description: 'open: a one-line task description.' },
            interventions: { type: 'string', description: 'close: how many times a person had to step in.' },
            verdict: { type: 'string', description: 'close: usable, fixed or discarded.' },
            note: { type: 'string', description: 'close: free-text note.' },
            items: { type: 'string', description: 'close: comma-separated work item ids the case produced.' },
            sessions: { type: 'string', description: 'close: comma-separated session ids.' },
            open: { type: 'boolean', description: 'list: only cases still open.' },
          },
          positional: ['action', 'name'],
          required: ['action'],
        },
        examples: ['fgos metrics case open login-fix --harness fgos --task "fix login"', 'fgos metrics case close login-fix --interventions 1 --verdict usable', 'fgos metrics case list --open'],
      },
      harness: {
        description: 'Harness scorecard over closed cases.',
        parameters: {
          type: 'object',
          properties: {
            case: { type: 'string', description: 'Only this case.' },
            since: { type: 'string', description: 'ISO date-time lower bound.' },
            until: { type: 'string', description: 'ISO date-time upper bound.' },
          },
          required: [],
        },
        examples: ['fgos metrics harness', 'fgos metrics harness --since 2026-10-01T00:00:00Z'],
      },
      faults: {
        description: 'Recorded faults, newest first.',
        parameters: {
          type: 'object',
          properties: {
            class: { type: 'string', description: 'Only this fault class.' },
            since: { type: 'string', description: 'ISO date-time lower bound.' },
            until: { type: 'string', description: 'ISO date-time upper bound.' },
            limit: { type: 'string', description: 'Positive integer: at most this many.' },
          },
          required: [],
        },
        examples: ['fgos metrics faults --limit 20'],
      },
      runs: {
        description: 'Run outcomes grouped by executor, adapter or role.',
        parameters: {
          type: 'object',
          properties: {
            by: { type: 'string', description: 'executor, adapter or role.', enum: ['executor', 'adapter', 'role'] },
            case: { type: 'string', description: 'Only runs of this case.' },
            since: { type: 'string', description: 'ISO date-time lower bound.' },
            until: { type: 'string', description: 'ISO date-time upper bound.' },
          },
          required: [],
        },
        examples: ['fgos metrics runs --by executor'],
      },
      coverage: {
        description: 'How many unit runs carry a readable run result.',
        parameters: { type: 'object', properties: {}, required: [] },
        examples: ['fgos metrics coverage'],
      },
      discussions: {
        description: 'Discussion panels and their passive stance agreement, grouped by workflow, executor or persona.',
        parameters: {
          type: 'object',
          properties: {
            by: { type: 'string', description: 'workflow, executor or persona.', enum: ['workflow', 'executor', 'persona'] },
            since: { type: 'string', description: 'ISO date-time lower bound.' },
            until: { type: 'string', description: 'ISO date-time upper bound.' },
          },
          required: [],
        },
        examples: ['fgos metrics discussions --by workflow'],
      },
      eval: {
        description: 'Eval records: "record" appends one read as a JSON object from stdin, "list" lists them (filters --harness, --question).',
        parameters: {
          type: 'object',
          properties: {
            action: { type: 'string', description: 'Positional: record or list.', enum: ['record', 'list'] },
            harness: { type: 'string', description: 'list: only this harness.' },
            question: { type: 'string', description: 'list: only this question.' },
          },
          positional: ['action'],
          required: ['action'],
        },
        examples: ['fgos metrics eval list', 'fgos metrics eval record < eval.json'],
      },
      outcomes: {
        description: 'Work item outcome counts from the work store.',
        parameters: { type: 'object', properties: {}, required: [] },
        examples: ['fgos metrics outcomes'],
      },
      entropy: {
        description: 'Work-graph entropy indicators.',
        parameters: { type: 'object', properties: {}, required: [] },
        examples: ['fgos metrics entropy'],
      },
      snapshot: {
        description: 'A point-in-time snapshot of the work store metrics.',
        parameters: { type: 'object', properties: {}, required: [] },
        examples: ['fgos metrics snapshot'],
      },
    },
    examples: ['fgos metrics ping', 'fgos metrics coverage', 'fgos metrics discussions --by workflow', 'fgos metrics eval list'],
    touchesState: true,
    requiresExistingStore: false,
    externalEffect: false,
    paginated: false,
    deprecated: null,
    nativeOnly: true,
  }),
  withSubcommands({
    name: 'friction',
    invoke: 'fgos friction <subcommand>',
    description: 'Observation friction recording, resolution, inspection, and ranking. Native Rust host command.',
    subcommands: {
      record: {
        description: 'Record one friction against a subject. --detail-stdin reads the detail text from stdin.',

      parameters: {
        type: 'object',
        properties: {
          subject: { type: 'string', description: 'kind:id, kind one of run, session, executor, case, work (e.g. work:tsk-abc).' },
          layer: { type: 'string', description: 'Where it hit: verification, state, environment, docs, spec, context, task, task-spec, executor or attestation.' },
          'error-class': { type: 'string', description: 'Error class.' },
          disposition: { type: 'string', description: 'advisory, blocked, parked or halted.' },
          producer: { type: 'string', description: 'Who records it.' },
          attempts: { type: 'string', description: 'Attempts before it resolved (integer).' },
          'doc-type': { type: 'string', description: 'Optional: tutorial, how-to, reference or explanation.' },
          detail: { type: 'string', description: 'Detail text.' },
          'detail-stdin': { type: 'boolean', description: 'Read the detail text from stdin instead of --detail.' },
        },
        required: ['subject', 'layer', 'error-class', 'disposition', 'producer'],
      },
      examples: ['fgos friction record --subject work:tsk-abc --layer verification --error-class usage --disposition advisory --producer agent --detail "flag missing"'],
    },
    resolve: {
      description: 'Mark a subject\'s friction resolved.',
      parameters: {
        type: 'object',
        properties: {
          subject: { type: 'string', description: 'kind:id, kind one of run, session, executor, case, work.' },
          reason: { type: 'string', description: 'answer, done, wontfix, clarify-pass or migrated.' },
          by: { type: 'string', description: 'Who resolved it.' },
        },
        required: ['subject', 'reason', 'by'],
      },
      examples: ['fgos friction resolve --subject work:tsk-abc --reason done --by agent'],
    },
    list: {
      description: 'List recorded frictions.',
      parameters: {
        type: 'object',
        properties: {
          kind: { type: 'string', description: 'Only subjects of this kind.' },
          layer: { type: 'string', description: 'Only this layer (see record --layer).' },
          since: { type: 'string', description: 'ISO date-time lower bound.' },
        },
        required: [],
      },
      examples: ['fgos friction list --layer verification'],
    },
    show: {
      description: 'Show one subject\'s frictions.',
      parameters: {
        type: 'object',
        properties: { subject: { type: 'string', description: 'Positional or --subject: kind:id (e.g. work:tsk-abc).' } },
        positional: ['subject'],
        required: ['subject'],
      },
      examples: ['fgos friction show work:tsk-abc'],
    },
    rank: {
      description: 'Subjects ranked by friction.',
      parameters: {
        type: 'object',
        properties: { limit: { type: 'string', description: 'At most this many (integer).' } },
        required: [],
      },
      examples: ['fgos friction rank --limit 10'],
    },
    ping: {
      description: 'Health check: echoes the resolved root.',
      parameters: { type: 'object', properties: {}, required: [] },
      examples: ['fgos friction ping'],
    },
    migrate: {
      description: 'Migrate legacy friction records into the friction store.',
      parameters: { type: 'object', properties: {}, required: [] },
      examples: ['fgos friction migrate'],
    },
  },
  examples: ['fgos friction ping', 'fgos friction rank --limit 10'],
  touchesState: false,
  requiresExistingStore: false,
  externalEffect: false,
  paginated: false,
  deprecated: null,
  nativeOnly: true,
}),
withSubcommands({
  name: 'convention',
  invoke: 'fgos convention <name|path|check|classify>',
  description: 'Generate and check repository artifact names and paths (reports, plans, journals) through the native Convention component. Use it instead of constructing such paths by hand.',
  subcommands: {
    name: {
      description: 'The file name for a new artifact of a kind.',
      parameters: {
        type: 'object',
        properties: {
          kind: { type: 'string', description: 'Artifact kind: report, plan or journal (inferred from --type when omitted).' },
          type: { type: 'string', description: 'Artifact type, e.g. audit, review; "plan" and "journal" imply that kind.' },
          slug: { type: 'string', description: 'Descriptive kebab-case slug.' },
          at: { type: 'string', description: 'Timestamp to name it at (default: now).' },
        },
        required: ['slug'],
      },
      examples: ['fgos convention name --kind report --type audit --slug x'],
    },
    path: {
      description: 'The repo-relative path for a new artifact of a kind.',
      parameters: {
        type: 'object',
        properties: {
          kind: { type: 'string', description: 'Artifact kind: report, plan or journal (inferred from --type when omitted).' },
          type: { type: 'string', description: 'Artifact type, e.g. audit, review; "plan" and "journal" imply that kind.' },
          slug: { type: 'string', description: 'Descriptive kebab-case slug.' },
          at: { type: 'string', description: 'Timestamp to name it at (default: now).' },
          plan: { type: 'string', description: 'Name (not path) of the plan directory a report belongs under, YYMMDD-HHMM-slug.' },
        },
        required: ['slug'],
      },
      examples: ['fgos convention path --kind report --type review --slug lane-x --plan 261014-1400-two-doors-one-rununit'],
    },
    check: {
      description: 'Check paths against the convention rules: exactly one of --all or explicit paths after "--".',
      parameters: {
        type: 'object',
        properties: {
          all: { type: 'boolean', description: 'Check every artifact in the repository.' },
          paths: { type: 'array', items: { type: 'string' }, description: 'Positional after "--": the paths to check.' },
        },
        positional: ['paths'],
        required: [],
      },
      examples: ['fgos convention check --all', 'fgos convention check -- plans/261014-1400-two-doors-one-rununit/reports/review-261014-2115-lane-x.md'],
    },
    classify: {
      description: 'Which placement rule (kind, cardinality, scope) one path falls under; a path no placement rule matches is refused (unknown-kind).',
      parameters: {
        type: 'object',
        properties: { path: { type: 'string', description: 'Positional after "--": the one path to classify.' } },
        positional: ['path'],
        required: ['path'],
      },
      examples: ['fgos convention classify -- fixtures/demo/spec.md'],
    },
  },
  examples: [
    'fgos convention name --kind report --type audit --slug x',
    'fgos convention check --all',
  ],
  touchesState: false,
  requiresExistingStore: false,
  externalEffect: false,
  paginated: false,
  deprecated: null,
  nativeOnly: true,
}),
{
  name: 'init',
  invoke: 'fgos init',
  description: 'Initialize the .fgos/ store in the current directory (event log, empty view, coexistence manifest).',
  parameters: { type: 'object', properties: {}, required: [] },
  examples: ['fgos init'],
  touchesState: true,
  requiresExistingStore: false,
  externalEffect: false,
  paginated: false,
  deprecated: null,
},
{
  name: 'add',
  invoke: 'fgos add',
  description: 'Add a work item directly with explicit fields (title/kind/risk/verify/description required). Omit id to auto-generate a collision-free "tsk-<hash>" id from title, same generator submit uses.',
  retiredFlags: ['tier'],
  parameters: {
    type: 'object',
    properties: {
      step: { type: 'string', description: "Workflow step the item enters at (e.g. discovery/planning/executing); omit for the default entry step." },
      'domain-fields': { type: 'string', description: "JSON-encoded object ({ [domainName]: {...} }) of domain-specific fields." },
      id: { type: 'string', description: 'Optional work item id (positional or --id); omit to auto-generate one from --title.' },
      title: { type: 'string', description: 'Work item title.' },
      kind: { type: 'string', description: 'Work item kind.' },
      risk: { type: 'string', description: 'Work item risk level.' },
      verify: { type: 'string', description: 'Verification command or plan for this item.' },
      // tsk-535 D1: REQUIRED, unlike `submit` (which always derives one
      // from the submitted text) -- `add` was the one write path that
      // could land an item with no description at all (measured: 20 of
      // 112 currently-broken items). No default fallback (e.g. silently
      // reusing --title): a required flag forces the caller to supply
      // real content instead of perpetuating the same content-free
      // duplication D2 explicitly avoids for decompose children.
      description: { type: 'string', description: 'Full-text intake description for this item (required).' },
      deps: { type: 'string', description: 'Comma-separated list of dependency ids.', multiValueFormat: 'csv' },
      refs: { type: 'string', description: 'Comma-separated list of reference ids/links.', multiValueFormat: 'csv' },
      learn: { type: 'string', description: 'Optional learning note.' },
      size: { type: 'string', description: 'Optional size (light/standard/heavy); omit to use the store default.' },
      rigor: { type: 'string', description: 'Optional rigor (low/standard/high/critical); omit to leave unset.' },
      domain: { type: 'string', description: 'Optional domain; omit to use the store default.' },
      footprint: { type: 'string', description: 'Optional comma-separated list of file paths this item is expected to touch (advisory only).', multiValueFormat: 'csv' },
      'discovered-from': { type: 'string', description: 'Optional id of the item this one was discovered from (provenance, not a dependency).' },
      parent: { type: 'string', description: 'Optional id of the item this one is a decomposed child of (lineage, not a dependency); omit to leave unset.' },
      'docs-ref': { type: 'string', description: 'Optional relative path to this item\'s docs/history/<feature>/ directory (its own CONTEXT.md/plan.md).' },
      acceptance: { type: 'string', description: 'Optional JSON-encoded array of {text, evidence} Condition-of-Satisfaction clauses (NOT comma-separated — clause text may contain commas).', multiValueFormat: 'json-array' },
      'goal-tier': { type: 'string', description: "Optional goal tier ('mvp' or 'milestone'); omit to leave unset (not a goal)." },
      targets: { type: 'string', description: 'Optional comma-separated list of ids this goal item considers "part of" it (an MVP\'s targets are milestone ids; a milestone\'s targets are ordinary work ids).', multiValueFormat: 'csv' },
      urgent: { type: 'string', description: 'Optional urgency level: one of low/medium/high/critical, human-entered. Omit to leave unset — the priority formula reads an absent value as medium, never stored as a default here.' },
    },
    positional: ['id'],
    required: ['title', 'kind', 'risk', 'verify', 'description'],
  },
  examples: [
    'fgos add build-cli --title "Build CLI" --kind feature --risk medium --verify "npm test" --description "Build the CLI entry point per the locked shape"',
    'fgos add --title "Build CLI" --kind feature --risk medium --verify "npm test" --description "Build the CLI entry point per the locked shape"',
  ],
  touchesState: true,
  requiresExistingStore: true,
  externalEffect: false,
  paginated: false,
  deprecated: null,
},
{
  name: 'submit',
  invoke: 'fgos submit',
  description: 'Intake a free-text description: derives the title, classifies tier/kind/risk, auto-generates an id, and adds the item.',
  retiredFlags: ['tier'],
  parameters: {
    type: 'object',
    properties: {
      unattended: { type: 'boolean', description: "Synonym of --async: do not wait for the discovery/planning run." },
      refs: { type: 'string', description: "Comma-separated reference ids/links." },
      parent: { type: 'string', description: "Lineage parent id." },
      footprint: { type: 'string', description: "Comma-separated file paths the item is expected to touch." },
      targets: { type: 'string', description: "Comma-separated target ids." },
      urgent: { type: 'string', description: "Urgency: low/medium/high/critical." },
      'goal-tier': { type: 'string', description: "Goal tier: mvp or milestone." },
      text: { type: 'string', description: 'Free-text description of the work (positional).' },
      async: { type: 'boolean', description: 'Mark as async/unattended (submitter does not stay to collaborate). Alias: --unattended.' },
      backlog: { type: 'boolean', description: 'Create the item directly at status "backlog" (an idea not yet committed to) instead of the default "todo". Promoting it to todo later is a human-only decision.' },
      domain: { type: 'string', description: 'Optional domain; omit to use the store default.' },
      'discovered-from': { type: 'string', description: 'Optional id of the item this one was discovered from (provenance, not a dependency).' },
      deps: { type: 'string', description: 'Comma-separated list of dependency ids.', multiValueFormat: 'csv' },
      acceptance: { type: 'string', description: 'Optional JSON-encoded array of {text, evidence} Condition-of-Satisfaction clauses (NOT comma-separated — clause text may contain commas).', multiValueFormat: 'json-array' },
      size: { type: 'string', description: 'Optional size override (e.g. light/standard/heavy); omit to use classify()\'s derived value.' },
      rigor: { type: 'string', description: 'Optional rigor (low/standard/high/critical); omit to leave unset.' },
      kind: { type: 'string', description: 'Optional kind override; omit to use classify()\'s derived value.' },
      risk: { type: 'string', description: 'Optional risk override; omit to use classify()\'s derived value.' },
      verify: { type: 'string', description: 'Optional verify override: the real, runnable verify command, when the submitter already knows it. Omit to use the placeholder sentinel until context-discovery designs one.' },
      'docs-ref': { type: 'string', description: 'Optional relative path to this item\'s docs/history/<feature>/ directory (its own CONTEXT.md/plan.md); omit to leave unset (can still be added later via edit --docs-ref).' },
    },
    positional: ['text'],
    required: ['text'],
  },
  examples: ['fgos submit "Fix the flaky retry test" --async', 'fgos submit "Fix the flaky retry test" --verify "npm test"'],
  touchesState: true,
  requiresExistingStore: true,
  externalEffect: false,
  paginated: false,

    required: ['id', 'text'],
  },
  examples: ['fgos answer build-cli --text "src/cli owns it."', 'fgos answer build-cli --approve --text "Split as proposed."'],
  touchesState: true,
  requiresExistingStore: true,
  externalEffect: false,
  paginated: false,
  deprecated: null,
},
{
